      <section class="card" aria-labelledby="notification-title">
        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-help">
              <legend id="notification-title">
                How do you prefer to receive notifications?
                <span class="required-mark" aria-hidden="true">*</span>
              </legend>
              <p id="notification-help" class="field-help">Required. Choose one option.</p>

              <div class="options">
                <label class="option">
                  <input type="radio" name="notifications" value="email" required>
                  <span class="option-label">Email</span>
                </label>

                <label class="option">
                  <input type="radio" name="notifications" value="sms" required>
                  <span class="option-label">SMS</span>
                </label>

                <label class="option">
                  <input type="radio" name="notifications" value="push" required>
                  <span class="option-label">Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <p class="status-message" id="form-status" role="status" aria-live="polite"></p>

