      radios.forEach((radio) => {
        const option = radio.closest('.option');
        if (option) {
          option.classList.toggle('is-selected', radio.checked);
        }
      });
    };

    radios.forEach((radio) => {
      radio.addEventListener('change', syncSelectionState);
    });

    syncSelectionState();

    form.addEventListener('submit', (event) => {
      if (!form.checkValidity()) {
        event.preventDefault();
        form.reportValidity();
        status.textContent = 'Please choose one notification preference.';
        status.dataset.tone = 'error';
        return;
      }

      event.preventDefault();
      const selected = radios.find((radio) => radio.checked);
      status.textContent = `Preference saved: ${selected ? selected.nextElementSibling.textContent : 'notifications'}.`;
      status.dataset.tone = 'success';
      syncSelectionState();
    });
