     .option input:focus-visible {
       outline: none;
       box-shadow: var(--focus);
       border-radius: 50%;
     }

     .option-label {
       font-weight: 600;
       letter-spacing: -0.01em;
     }

     .option.is-selected {
       border-color: rgba(38, 93, 242, 0.4);
       background: linear-gradient(180deg, rgba(232, 239, 255, 0.9), rgba(255, 255, 255, 0.98));
       box-shadow: 0 14px 30px rgba(38, 93, 242, 0.12);
