       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.9rem 1.35rem;
       font: inherit;
       font-weight: 700;
       color: #fff;
       background: linear-gradient(135deg, #2f6bff, #2452d8);
       box-shadow: 0 12px 28px rgba(36, 82, 216, 0.24);
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
     }

     .submit-button:hover {
       transform: translateY(-1px);
       filter: brightness(1.02);
       box-shadow: 0 16px 34px rgba(36, 82, 216, 0.28);
     }

     .submit-button:focus-visible {
       outline: none;
       box-shadow: var(--focus), 0 12px 28px rgba(36, 82, 216, 0.24);
     }

     @media (max-width: 30rem) {
       main {
         padding-top: 4rem;
       }

       .card {
         padding: 1rem;
