        <h1>Choose how to receive updates</h1>
        <p class="intro">Pick the notification channel that fits your workflow best.</p>
      </header>

      <section class="card" aria-labelledby="notification-title">
        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-help">
              <legend id="notification-title">
                How do you prefer to receive notifications?
                <span class="required-mark" aria-hidden="true">*</span>
              </legend>
              <p id="notification-help" class="field-help">Required. Choose one option.</p>

              <div class="options">
                <label class="option">
                  <input type="radio" name="notifications" value="email" required>
                  <span class="option-label">Email</span>
                </label>

                <label class="option">
                  <input type="radio" name="notifications" value="sms" required>
                  <span class="option-label">SMS</span>
                </label>

                <label class="option">
                  <input type="radio" name="notifications" value="push" required>
                  <span class="option-label">Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <p class="status-message" id="form-status" role="status" aria-live="polite"></p>

          <div class="actions">
            <button class="submit-button" type="submit">Save preference</button>
          </div>
        </form>
      </section>
    </div>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const status = document.getElementById('form-status');
    const radios = Array.from(form.querySelectorAll('input[type="radio"][name="notifications"]'));

    const syncSelectionState = () => {
      radios.forEach((radio) => {
        const option = radio.closest('.option');
        if (option) {
          option.classList.toggle('is-selected', radio.checked);
        }
      });
    };

    radios.forEach((radio) => {
      radio.addEventListener('change', syncSelectionState);
    });

    syncSelectionState();

    form.addEventListener('submit', (event) => {
      if (!form.checkValidity()) {
        event.preventDefault();
        form.reportValidity();
        status.textContent = 'Please choose one notification preference.';
        status.dataset.tone = 'error';
        return;
      }

      event.preventDefault();
      const selected = radios.find((radio) => radio.checked);
      status.textContent = `Preference saved: ${selected ? selected.nextElementSibling.textContent : 'notifications'}.`;
      status.dataset.tone = 'success';
      syncSelectionState();
    });
  </script>
</body>
